package edu.team12.deadlocklab.recovery;
import edu.team12.deadlocklab.domain.*;import java.util.*;
public final class RecoveryService {
 public Scenario terminate(Scenario s,String victim){validate(s);int i=s.processes().indexOf(victim);if(i<0||s.terminated().contains(victim))throw new IllegalArgumentException("victim must be an active process");List<Integer>a=new ArrayList<>(s.available());for(int j=0;j<a.size();j++)a.set(j,a.get(j)+s.allocation().get(i).get(j));List<List<Integer>>al=copy(s.allocation()),rq=copy(s.request());for(int j=0;j<a.size();j++)al.get(i).set(j,0);List<String>dead=new ArrayList<>(s.terminated());dead.add(victim);Scenario out=s.withState(s.processes(),a,al,rq,dead);ensure(out);return out;}
 public Scenario preempt(Scenario s,String victim,String resource){validate(s);int i=s.processes().indexOf(victim),j=s.resources().indexOf(resource);if(i<0||j<0||s.terminated().contains(victim))throw new IllegalArgumentException("victim and resource must identify an active process and resource");if(!s.preemptible().get(j))throw new IllegalArgumentException("resource is not configured as preemptible");int count=s.allocation().get(i).get(j);if(count==0)throw new IllegalArgumentException("victim holds no instances of this resource");List<Integer>a=new ArrayList<>(s.available());a.set(j,a.get(j)+count);List<List<Integer>>al=copy(s.allocation()),rq=copy(s.request());al.get(i).set(j,0);rq.get(i).set(j,rq.get(i).get(j)+count);Scenario out=s.withState(s.processes(),a,al,rq,s.terminated());ensure(out);return out;}
 public Scenario rollback(Scenario checkpoint){validate(checkpoint);return checkpoint;}
 private void validate(Scenario s){ensure(s);}private void ensure(Scenario s){List<String>e=ScenarioValidator.errors(s);if(!e.isEmpty())throw new IllegalArgumentException(String.join("; ",e));}
 private List<List<Integer>>copy(List<List<Integer>>m){return m.stream().map(ArrayList::new).map(x->(List<Integer>)x).collect(java.util.stream.Collectors.toCollection(ArrayList::new));}
}
